/* std_embed.h — the standard library sources compiled into the binary.
 *
 * src/std_embed.c is generated by tools/embed.c from std/ (the Makefile
 * regenerates it whenever std/ changes) and committed, so the one-command
 * build needs nothing else. Contents are stored as string-literal chunks
 * to respect compiler limits on literal length; use tern_std_text() to get
 * a file as one contiguous string. */
#ifndef TERN_STD_EMBED_H
#define TERN_STD_EMBED_H

#include "base/common.h"

typedef struct StdEmbedFile {
    const char *path;              /* "std/stream/stream.tern" ('/'-separated) */
    const char *const *chunks;     /* concatenated, these are the file contents */
    size_t nchunks;
    size_t len;                    /* total byte length */
} StdEmbedFile;

extern const StdEmbedFile tern_std_files[];   /* sorted by path */
extern const size_t tern_std_file_count;

/* Contents of file i as one NUL-terminated string (assembled on first use
 * and cached for the life of the process). */
const char *tern_std_text(size_t i);

#endif /* TERN_STD_EMBED_H */
